/**
 * Scriptures world — data contracts. The static JSON under public/scriptures/
 * is generated by scripts/scriptures/build-data.mjs from public-domain sources
 * (see public/scriptures/SOURCES.md); these types mirror that output exactly.
 */

export type TranslationId = "web" | "kjv" | "drb" | "brenton" | "charles";

export type BookMeta = {
  name: string;
  chapters: number;
  /** Translations that actually contain this book. */
  trans: TranslationId[];
};

export type Tradition = {
  id: string;
  name: string;
  blurb: string;
  /** Present when part of this tradition's canon can't be hosted yet. */
  editorial?: string;
  linkOut?: { label: string; url: string };
  /** Book IDs in this tradition's canonical order. */
  books: string[];
  /** Ordered preference; the reader picks the first available per book. */
  transPreference: TranslationId[];
};

export type Canons = {
  /** Global superset order; search postings index into this. */
  bookOrder: string[];
  books: Record<string, BookMeta>;
  translations: Record<TranslationId, { name: string; year: string; license: string }>;
  traditions: Tradition[];
};

/** A claim on a tradition page with explicit evidence. */
export type TraditionClaim = {
  title: string;
  text: string;
  sourceIds: string[];
  /** Hosted books that make the claim concrete in this site's reader. */
  bookIds?: string[];
};

export type TraditionBriefing = {
  tradition: string;
  traditionName: string;
  /** One sentence that identifies the represented canonical family. */
  oneLine: string;
  /** A short orientation that distinguishes a church tradition from a book count. */
  orient: string;
  /** The first caution a reader needs before comparing shelves. */
  keepInMind: string;
  facts: {
    label: string;
    value: string;
    sourceIds: string[];
  }[];
  /** Historical moments that explain how this received collection took shape. */
  formation: {
    date: string;
    title: string;
    text: string;
    sourceIds: string[];
  }[];
  /** Books, arrangements, or boundaries that distinguish this shelf. */
  distinctives: TraditionClaim[];
  /** How this community receives, reads, and uses Scripture. */
  reception: TraditionClaim[];
  /** Variation that a single route label would otherwise conceal. */
  variations: TraditionClaim[];
  debates: {
    question: string;
    settled?: string;
    positions: {
      view: string;
      grounds: string;
      sourceIds: string[];
    }[];
    soWhat?: string;
  }[];
  /** Honest boundary between the tradition's received corpus and this hosted shelf. */
  hosting: {
    heading: string;
    summary: string;
    available: string;
    unavailable?: string;
    sourceIds: string[];
  };
  sources: BriefingSource[];
};

export type BookText = {
  trans: TranslationId;
  book: string;
  name: string;
  /** chapters[0] = chapter 1; verse index 0 = verse 1; "" = bridged/absent verse. */
  chapters: string[][];
};

export type OriginalLanguage = "hebrew" | "aramaic" | "greek";
export type OriginalEditionId = "oshb" | "sblgnt" | "lxx";

/** One source-language word with the source project's lexical analysis. */
export type OriginalWord = {
  /** Pointed/polytonic surface form, including Greek punctuation when present. */
  text: string;
  /** OSHB lexical identifiers for Semitic text; a Greek lexical form for MorphGNT/lxx-morph. */
  lemma: string;
  /** Unmodified morphology code or parsing string from OSHB, MorphGNT, or lxx-morph. */
  morph: string;
  /** Source-supplied part of speech when it is separate from the morphology string. */
  pos?: string;
  /** Source-reported confidence for automated lexical analysis. */
  analysisConfidence?: "high" | "medium" | "low";
  /** Source-reported analysis path, such as `morpheus` or `context_resolved`. */
  analysisSource?: string;
  /** Stable OSHB word ID. The Greek datasets do not supply one. */
  id?: string;
  /** Masoretic punctuation or section marker following this word. */
  after?: string;
  /** Written consonantal form when the displayed, pointed qere differs. */
  ketiv?: string;
};

export type OriginalVerse = {
  number: number;
  languages: OriginalLanguage[];
  words: OriginalWord[];
  /** Masoretic references retained when this site's English numbering differs. */
  sourceRefs?: string[];
};

export type OriginalChapter = {
  book: string;
  bookName: string;
  chapter: number;
  edition: OriginalEditionId;
  direction: "ltr" | "rtl";
  verses: OriginalVerse[];
};

export type OriginalManifest = {
  generatedAt: string;
  books: Record<string, OriginalEditionId>;
  chapterCounts: Record<string, number>;
  /** LXX books are reader-visible only for translations with identical numbering. */
  readerTranslations?: Partial<Record<string, TranslationId[]>>;
  editions: Record<
    OriginalEditionId,
    {
      name: string;
      description: string;
      source: string;
      revision: string;
      textLicense: string;
      dataLicense: string;
      attribution: string;
    }
  >;
};

export type XrefFile = {
  book: string;
  /** Keyed "chapter:verse" → target refs like "JHN 1:1-3". */
  refs: Record<string, string[]>;
};

/** [bookOrder index, chapter, verse] */
export type SearchPosting = [number, number, number];
export type SearchShard = Record<string, SearchPosting[]>;
export type SearchMeta = { trans: TranslationId; stopwords: string[]; shardScheme: string };

export type VerseHit = {
  book: string;
  chapter: number;
  verse: number;
  /** Distinct query tokens matched; higher first. */
  matched: number;
};

/** A parsed cross-reference target. */
export type ParsedRef = {
  book: string;
  chapter: number;
  verse: number;
  endVerse?: number;
  label: string;
};

/** One bullet point under a Nave's Topical Bible subject. */
export type NaveItem = {
  label: string;
  refs: string[];
  /** Points to another subject id, when this bullet is a cross-reference ("-See X"). */
  see?: string;
  /** 1 = an indented sub-point under the item above it. */
  depth: number;
};

export type NaveTopic = {
  id: string;
  section: string;
  items: NaveItem[];
};

export type NaveTopicFile = {
  topics: NaveTopic[];
};

/** The full A-Z topic list — for browsing/searching without loading every shard. */
export type NaveIndex = {
  topics: { id: string; section: string; refCount: number }[];
};

/** Chapter cheat sheet — zero-background deep dive, AI-generated at build, stored static. */
export type ChapterGuideQuestion = {
  id: string;
  question: string;
  answer: string;
  verseRefs: string[];
  category: "context" | "word" | "theology" | "history" | "practical" | "hard_verse";
  relatedVerses?: number[];
  /** External evidence from the book briefing, distinct from the cited verses. */
  evidenceSourceIds?: string[];
};

export type ChapterReadingContext = {
  text: string;
  /** Chapter-qualified references within this book, including adjacent chapters. */
  verseRefs: string[];
  evidenceSourceIds?: string[];
};

export type ChapterGuide = {
  book: string;
  chapter: number;
  bookName: string;
  summary: string;
  whyItMatters: string;
  /** Literary continuity, shown before the text when an authored record exists. */
  readingContext?: {
    before: ChapterReadingContext;
    here: ChapterReadingContext;
    after: ChapterReadingContext;
  };
  /** Bind continuity notes to the whole edition, including neighboring chapters. */
  readingContextSource?: { translation: TranslationId; textHash: string };
  /** Book-briefing sources supporting authorship, date, or other background. */
  contextSourceIds?: string[];
  context: {
    author?: string;
    audience?: string;
    date?: string;
    setting?: string;
    literaryForm?: string;
  };
  outline: { heading: string; verses: string; note?: string }[];
  keyVerses: { ref: string; text: string; why: string }[];
  themes: string[];
  questions: ChapterGuideQuestion[];
  glossary?: { term: string; def: string }[];
  /**
   * Reproducible model provenance, split by what the pipeline can actually
   * know. Software cannot verify which model wrote text it did not call, so
   * the schema stops pretending it can:
   *
   *   direct-generation — `model` is MEASURED. The build issued the request
   *                       and this is what answered it.
   *   review-bound      — `attributedModel` is ASSERTED by the named reviewer
   *                       for a draft written outside the pipeline. It carries
   *                       exactly as much weight as that reviewer does.
   *
   * The two never share a field. A guide once shipped with `model:
   * "gemini-2.5-pro"` typed in by hand — no Gemini call had been made, the key
   * was dead, and the page told every reader that model wrote it. Keeping the
   * asserted value in its own field is what makes that impossible to restate
   * as a measurement. Neither method is an editorial approval by itself.
   */
  generation?: {
    /** Present only for direct-generation: the model the build observed. */
    model?: string;
    /** Present only for review-bound: who or what the reviewer says drafted it. */
    attributedModel?: string;
    promptHash: string;
    generatedAt: string;
    rubricVersion: string;
    method: "direct-generation" | "review-bound";
    /**
     * Present only when `promptHash` was moved after a citation url/label
     * correction to the book briefing — the one grounding change that cannot
     * alter what a chapter says. Each entry is the audit trail for one move:
     * when, who, why, the hash the guide was bound to before, and exactly
     * which grounding fields differed. The validator rejects any record that
     * names a field outside citation metadata, so a re-bind can never stand
     * in for the review a substantive change would need.
     */
    rebound?: {
      at: string;
      by: string;
      reason: string;
      previousPromptHash: string;
      changedFields: string[];
    }[];
  };
  /**
   * Editorial review record — who judged the guide's claims, when, and
   * against which hosted translations. Absent means unreviewed; the
   * corpus-health snapshot publishes the counts by tier. "human-reviewed"
   * is the only tier that implies a person signed off.
   */
  reviewStatus?: "agent-reviewed" | "human-reviewed";
  reviewedAt?: string;
  reviewer?: string;
  sourceIds?: string[];
};

/**
 * Book briefing — the context a reader needs BEFORE verse 1, written by hand
 * against the hosted text and public-domain primary sources. Not generated.
 *
 * The shape follows what a good briefing gives anyone walking into unfamiliar
 * work: where you are, who is in it, what kind of writing this is and how to
 * read it, what it is driving at, what will trip you, and — where the evidence
 * genuinely runs out — who disagrees and why.
 */

/** An outside witness or piece of evidence a claim rests on. */
export type BriefingSource = {
  /** Stable key used by claim-level citations inside the briefing. */
  id: string;
  /** e.g. "Papias, Fragment VI (c. AD 95–140)" */
  label: string;
  /** What it actually says, in plain words. */
  says: string;
  /** Route to the text hosted on this site, when we host it. */
  href?: string;
  /** External source, when we do not host it. */
  url?: string;
};

/** A question where honest readers land in different places. */
export type BriefingDebate = {
  question: string;
  /** What is NOT actually in dispute — stated first so the split stays in proportion. */
  settled?: string;
  positions: {
    view: string;
    /** The case for it, including who holds it. */
    grounds: string;
  }[];
  /** Why it matters to a reader, or why it may not. */
  soWhat?: string;
};

export type BookBriefing = {
  book: string;
  bookName: string;
  /** One sentence. What this book is, before anything else. */
  oneLine: string;
  /** The orientation paragraph — 3-5 sentences. */
  orient: string;
  /** What has already happened when this book opens. */
  whereYouAre: string;
  facts: {
    writtenBy?: string;
    writtenWhen?: string;
    writtenFor?: string;
    place?: string;
    covers?: string;
    /** Measured from the hosted text, not estimated. */
    size?: string;
  };
  /** Evidence for the matching book-level facts, resolved through sources. */
  factSourceIds?: Partial<Record<"writtenBy" | "writtenWhen" | "writtenFor" | "place" | "covers" | "size", string[]>>;
  /**
   * The linguistic layers a translation can otherwise collapse: the language
   * of the book, the languages in its narrated world, signals the author gives
   * the reader, and what the hosted English can or cannot establish.
   */
  language?: {
    writtenIn: string;
    /** The social/literary level and texture of the book's language. */
    register?: string;
    spokenWorld?: string;
    readerSignal?: string;
    englishLayer: string;
    /**
     * Composition and transmission are different claims. These layers keep a
     * multilingual book (or a translated form that became canonical) from
     * being reduced to one misleading "original language" label.
     */
    textualHistory?: {
      label: string;
      language: string;
      role: "composition" | "section" | "translation" | "earliest-extant";
      /** Verse spans when the layer applies only to part of the book. */
      spans?: string[];
      description: string;
      sourceIds: string[];
    }[];
    /** Recurring features that shape how the original language sounds and moves. */
    features?: {
      title: string;
      /** Original-script form plus transliteration and gloss, where useful. */
      original?: string;
      explanation: string;
      translationNote?: string;
      caution?: string;
      refs?: string[];
      sourceIds: string[];
    }[];
    examplesHeading?: string;
    examples?: {
      ref: string;
      form: string;
      meaning: string;
      why: string;
      sourceIds: string[];
    }[];
  };
  /** Genre — and how to read that genre, which is the part usually left out. */
  form: { name: string; how: string };
  /** Who you will meet. */
  cast?: { name: string; who: string }[];
  /**
   * The shape of the book. `chapters` is a whole-chapter range so the reader's
   * chapter grid can group by it without hiding or duplicating a number;
   * `precise` carries the real verse boundary when a section turns mid-chapter.
   */
  shape: { heading: string; chapters: string; precise?: string; note?: string }[];
  /** What the book is driving at. */
  purpose: string;
  /** Things that reliably trip a first-time reader, and the help for each. */
  snags: { snag: string; help: string }[];
  /** The honesty layer. */
  debates?: BriefingDebate[];
  /** Where the outside evidence comes from. */
  sources?: BriefingSource[];
  /** Practical entry points. */
  howToRead: { tip: string; refs?: string[] }[];
  /** Where to go when you finish. */
  next: string;
  /** Where the book sits when traditions place or count it differently. */
  traditionNote?: string;
};

/**
 * One chapter's computed semantic neighbours — "chapters that carry this
 * idea". Built by scripts/scriptures/build-neighbors.mjs from the same
 * embedding store the reader's meaning search uses, so it is arithmetic over
 * the hosted text rather than an editor's judgement. `xrefLinks` records how
 * many times the Treasury of Scripture Knowledge already joins a verse of this
 * chapter to a verse of the neighbour, so agreement stays visible.
 */
export type ChapterNeighbours = {
  book: string;
  chapter: number;
  neighbours: {
    book: string;
    chapter: number;
    /** Cosine similarity of the two chapter centroids. */
    score: number;
    xrefLinks: number;
  }[];
};
